-- SEC-070 Asset Security. Aplicar primeiro em DEV.
ALTER TABLE assets ADD COLUMN manufacturer text,ADD COLUMN model text,ADD COLUMN serial_number text,ADD COLUMN manufacture_year smallint,ADD COLUMN geofence_enabled boolean NOT NULL DEFAULT false,ADD COLUMN geofence_state text NOT NULL DEFAULT 'unknown',ADD COLUMN last_position_at timestamptz,ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now(),ADD COLUMN notes text;
ALTER TABLE assets ADD CONSTRAINT assets_status_allowed CHECK(status IN('active','maintenance','inactive')),ADD CONSTRAINT assets_geofence_state_allowed CHECK(geofence_state IN('unknown','inside','outside')),ADD CONSTRAINT assets_manufacture_year_valid CHECK(manufacture_year IS NULL OR manufacture_year BETWEEN 1900 AND 2200),ADD CONSTRAINT assets_notes_length CHECK(notes IS NULL OR length(notes)<=4000);
CREATE UNIQUE INDEX assets_org_serial_uq ON assets(organization_id,serial_number) WHERE serial_number IS NOT NULL;CREATE INDEX idx_assets_property_status ON assets(property_id,status) WHERE property_id IS NOT NULL;
CREATE TABLE asset_positions(id bigserial PRIMARY KEY,organization_id uuid NOT NULL REFERENCES organizations(id),asset_id uuid NOT NULL REFERENCES assets(id) ON DELETE CASCADE,device_id uuid REFERENCES devices(id),source_event_id text,position geography(Point,4326) NOT NULL,recorded_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),speed_kmh numeric,heading_degrees numeric,accuracy_m numeric,inside_geofence boolean,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,CONSTRAINT asset_positions_speed_valid CHECK(speed_kmh IS NULL OR speed_kmh>=0),CONSTRAINT asset_positions_heading_valid CHECK(heading_degrees IS NULL OR(heading_degrees>=0 AND heading_degrees<360)),CONSTRAINT asset_positions_accuracy_valid CHECK(accuracy_m IS NULL OR accuracy_m>=0),CONSTRAINT asset_positions_source_length CHECK(source_event_id IS NULL OR length(source_event_id)<=128));CREATE UNIQUE INDEX asset_positions_asset_event_uq ON asset_positions(asset_id,source_event_id) WHERE source_event_id IS NOT NULL;CREATE INDEX idx_asset_positions_asset_time ON asset_positions(asset_id,recorded_at DESC);
CREATE TABLE asset_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),asset_id uuid NOT NULL REFERENCES assets(id) ON DELETE CASCADE,document_type text NOT NULL,title text NOT NULL,document_reference text,issued_at date,expires_at date,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','expired','replaced','cancelled')),storage_status text NOT NULL DEFAULT 'not_configured' CHECK(storage_status IN('not_configured','private_future')),created_by_user_id uuid REFERENCES app_users(id),created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT asset_documents_title_length CHECK(length(title) BETWEEN 2 AND 160),CONSTRAINT asset_documents_type_length CHECK(length(document_type) BETWEEN 2 AND 80));CREATE INDEX idx_asset_documents_asset_expiry ON asset_documents(asset_id,expires_at);
CREATE TABLE asset_maintenance(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),asset_id uuid NOT NULL REFERENCES assets(id) ON DELETE CASCADE,maintenance_type text NOT NULL,description text,scheduled_at timestamptz,completed_at timestamptz,status text NOT NULL DEFAULT 'planned' CHECK(status IN('planned','in_progress','completed','cancelled')),meter_hours numeric,created_by_user_id uuid REFERENCES app_users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT asset_maintenance_description_length CHECK(description IS NULL OR length(description)<=4000),CONSTRAINT asset_maintenance_meter_valid CHECK(meter_hours IS NULL OR meter_hours>=0));CREATE INDEX idx_asset_maintenance_asset_status ON asset_maintenance(asset_id,status,scheduled_at);
ALTER TABLE asset_positions ENABLE ROW LEVEL SECURITY;ALTER TABLE asset_documents ENABLE ROW LEVEL SECURITY;ALTER TABLE asset_maintenance ENABLE ROW LEVEL SECURITY;
CREATE POLICY asset_positions_scope_read ON asset_positions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM assets a JOIN properties p ON p.id=a.property_id WHERE a.id=asset_positions.asset_id AND app_has_scope_access(a.organization_id,p.neighborhood_id,a.property_id)));CREATE POLICY asset_documents_scope_read ON asset_documents FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM assets a JOIN properties p ON p.id=a.property_id WHERE a.id=asset_documents.asset_id AND app_has_scope_access(a.organization_id,p.neighborhood_id,a.property_id)));CREATE POLICY asset_maintenance_scope_read ON asset_maintenance FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM assets a JOIN properties p ON p.id=a.property_id WHERE a.id=asset_maintenance.asset_id AND app_has_scope_access(a.organization_id,p.neighborhood_id,a.property_id)));REVOKE INSERT,UPDATE,DELETE ON assets,asset_positions,asset_documents,asset_maintenance FROM authenticated,anonymous;GRANT SELECT ON asset_positions,asset_documents,asset_maintenance TO authenticated;
-- Cadastro e gestão
CREATE OR REPLACE FUNCTION register_asset(p_property_id uuid,p_name text,p_asset_type text,p_external_identifier text DEFAULT NULL,p_device_id uuid DEFAULT NULL,p_manufacturer text DEFAULT NULL,p_model text DEFAULT NULL,p_serial_number text DEFAULT NULL,p_manufacture_year smallint DEFAULT NULL,p_latitude double precision DEFAULT NULL,p_longitude double precision DEFAULT NULL,p_geofence_geojson text DEFAULT NULL,p_notes text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$DECLARE v_org uuid;v_neigh uuid;v_device_org uuid;v_device_prop uuid;v_device_type device_type;v_location geography(Point,4326);v_geofence geometry(Polygon,4326);v_id uuid:=gen_random_uuid();BEGIN SELECT organization_id,neighborhood_id INTO v_org,v_neigh FROM properties WHERE id=p_property_id;IF NOT FOUND THEN RAISE EXCEPTION 'property_not_found';END IF;IF NOT app_can_manage_property(p_property_id) THEN RAISE EXCEPTION 'property_management_required';END IF;IF COALESCE(btrim(p_name),'')='' OR length(btrim(p_name))>160 THEN RAISE EXCEPTION 'invalid_asset_name';END IF;IF COALESCE(btrim(p_asset_type),'')='' OR length(btrim(p_asset_type))>80 THEN RAISE EXCEPTION 'invalid_asset_type';END IF;IF p_manufacture_year IS NOT NULL AND p_manufacture_year NOT BETWEEN 1900 AND 2200 THEN RAISE EXCEPTION 'invalid_manufacture_year';END IF;IF(p_latitude IS NULL)<>(p_longitude IS NULL) THEN RAISE EXCEPTION 'latitude_longitude_pair_required';END IF;IF p_latitude IS NOT NULL THEN IF p_latitude NOT BETWEEN -90 AND 90 OR p_longitude NOT BETWEEN -180 AND 180 THEN RAISE EXCEPTION 'invalid_coordinates';END IF;v_location:=ST_SetSRID(ST_MakePoint(p_longitude,p_latitude),4326)::geography;END IF;IF p_device_id IS NOT NULL THEN SELECT organization_id,property_id,device_type INTO v_device_org,v_device_prop,v_device_type FROM devices WHERE id=p_device_id;IF NOT FOUND THEN RAISE EXCEPTION 'device_not_found';END IF;IF v_device_org<>v_org OR v_device_prop IS DISTINCT FROM p_property_id OR v_device_type<>'gps'::device_type THEN RAISE EXCEPTION 'gps_device_scope_mismatch';END IF;END IF;IF p_geofence_geojson IS NOT NULL AND btrim(p_geofence_geojson)<>'' THEN BEGIN v_geofence:=ST_SetSRID(ST_GeomFromGeoJSON(p_geofence_geojson),4326)::geometry(Polygon,4326);EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'invalid_geofence';END;IF NOT ST_IsValid(v_geofence) OR ST_IsEmpty(v_geofence) THEN RAISE EXCEPTION 'invalid_geofence';END IF;END IF;INSERT INTO assets(id,organization_id,property_id,name,asset_type,external_identifier,device_id,location,geofence,status,manufacturer,model,serial_number,manufacture_year,geofence_enabled,geofence_state,last_position_at,updated_at,notes) VALUES(v_id,v_org,p_property_id,btrim(p_name),btrim(p_asset_type),NULLIF(btrim(p_external_identifier),''),p_device_id,v_location,v_geofence,'active',NULLIF(btrim(p_manufacturer),''),NULLIF(btrim(p_model),''),NULLIF(btrim(p_serial_number),''),p_manufacture_year,v_geofence IS NOT NULL,'unknown',CASE WHEN v_location IS NOT NULL THEN now() ELSE NULL END,now(),NULLIF(btrim(p_notes),''));INSERT INTO audit_logs(organization_id,actor_user_id,action,entity_type,entity_id,details) VALUES(v_org,app_current_user_id(),'asset.registered','asset',v_id,jsonb_build_object('propertyId',p_property_id,'assetType',p_asset_type,'gpsDeviceId',p_device_id,'geofenceEnabled',v_geofence IS NOT NULL));RETURN v_id;END$$;GRANT EXECUTE ON FUNCTION register_asset(uuid,text,text,text,uuid,text,text,text,smallint,double precision,double precision,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION set_asset_geofence_radius(p_asset_id uuid,p_latitude double precision,p_longitude double precision,p_radius_m numeric) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$DECLARE v_org uuid;v_prop uuid;v_polygon geometry(Polygon,4326);BEGIN SELECT organization_id,property_id INTO v_org,v_prop FROM assets WHERE id=p_asset_id;IF NOT FOUND THEN RAISE EXCEPTION 'asset_not_found';END IF;IF v_prop IS NULL OR NOT app_can_manage_property(v_prop) THEN RAISE EXCEPTION 'asset_management_required';END IF;IF p_latitude NOT BETWEEN -90 AND 90 OR p_longitude NOT BETWEEN -180 AND 180 THEN RAISE EXCEPTION 'invalid_coordinates';END IF;IF p_radius_m IS NULL OR p_radius_m<10 OR p_radius_m>100000 THEN RAISE EXCEPTION 'invalid_radius';END IF;v_polygon:=ST_Buffer(ST_SetSRID(ST_MakePoint(p_longitude,p_latitude),4326)::geography,p_radius_m)::geometry(Polygon,4326);UPDATE assets SET geofence=v_polygon,geofence_enabled=true,geofence_state='unknown',updated_at=now() WHERE id=p_asset_id;INSERT INTO audit_logs(organization_id,actor_user_id,action,entity_type,entity_id,details) VALUES(v_org,app_current_user_id(),'asset.geofence_radius_set','asset',p_asset_id,jsonb_build_object('latitude',p_latitude,'longitude',p_longitude,'radiusM',p_radius_m));RETURN true;END$$;GRANT EXECUTE ON FUNCTION set_asset_geofence_radius(uuid,double precision,double precision,numeric) TO authenticated;
CREATE OR REPLACE FUNCTION add_asset_document(p_asset_id uuid,p_document_type text,p_title text,p_document_reference text DEFAULT NULL,p_issued_at date DEFAULT NULL,p_expires_at date DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$DECLARE v_org uuid;v_prop uuid;v_id uuid:=gen_random_uuid();BEGIN SELECT organization_id,property_id INTO v_org,v_prop FROM assets WHERE id=p_asset_id;IF NOT FOUND THEN RAISE EXCEPTION 'asset_not_found';END IF;IF v_prop IS NULL OR NOT app_can_manage_property(v_prop) THEN RAISE EXCEPTION 'asset_management_required';END IF;IF COALESCE(btrim(p_document_type),'')='' OR COALESCE(btrim(p_title),'')='' THEN RAISE EXCEPTION 'document_fields_required';END IF;IF p_expires_at IS NOT NULL AND p_issued_at IS NOT NULL AND p_expires_at<p_issued_at THEN RAISE EXCEPTION 'invalid_document_dates';END IF;INSERT INTO asset_documents(id,organization_id,asset_id,document_type,title,document_reference,issued_at,expires_at,status,storage_status,created_by_user_id) VALUES(v_id,v_org,p_asset_id,btrim(p_document_type),btrim(p_title),NULLIF(btrim(p_document_reference),''),p_issued_at,p_expires_at,CASE WHEN p_expires_at IS NOT NULL AND p_expires_at<current_date THEN 'expired' ELSE 'active' END,'not_configured',app_current_user_id());RETURN v_id;END$$;GRANT EXECUTE ON FUNCTION add_asset_document(uuid,text,text,text,date,date) TO authenticated;
CREATE OR REPLACE FUNCTION schedule_asset_maintenance(p_asset_id uuid,p_maintenance_type text,p_description text DEFAULT NULL,p_scheduled_at timestamptz DEFAULT NULL,p_meter_hours numeric DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$DECLARE v_org uuid;v_prop uuid;v_id uuid:=gen_random_uuid();BEGIN SELECT organization_id,property_id INTO v_org,v_prop FROM assets WHERE id=p_asset_id;IF NOT FOUND THEN RAISE EXCEPTION 'asset_not_found';END IF;IF v_prop IS NULL OR NOT app_can_manage_property(v_prop) THEN RAISE EXCEPTION 'asset_management_required';END IF;IF COALESCE(btrim(p_maintenance_type),'')='' THEN RAISE EXCEPTION 'maintenance_type_required';END IF;INSERT INTO asset_maintenance(id,organization_id,asset_id,maintenance_type,description,scheduled_at,status,meter_hours,created_by_user_id) VALUES(v_id,v_org,p_asset_id,btrim(p_maintenance_type),NULLIF(btrim(p_description),''),p_scheduled_at,'planned',p_meter_hours,app_current_user_id());RETURN v_id;END$$;GRANT EXECUTE ON FUNCTION schedule_asset_maintenance(uuid,text,text,timestamptz,numeric) TO authenticated;
CREATE OR REPLACE FUNCTION update_asset_maintenance_status(p_maintenance_id uuid,p_status text,p_note text DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$DECLARE v_org uuid;v_prop uuid;v_asset uuid;BEGIN SELECT m.organization_id,m.asset_id,a.property_id INTO v_org,v_asset,v_prop FROM asset_maintenance m JOIN assets a ON a.id=m.asset_id WHERE m.id=p_maintenance_id;IF NOT FOUND THEN RAISE EXCEPTION 'maintenance_not_found';END IF;IF v_prop IS NULL OR NOT app_can_manage_property(v_prop) THEN RAISE EXCEPTION 'asset_management_required';END IF;IF p_status NOT IN('planned','in_progress','completed','cancelled') THEN RAISE EXCEPTION 'invalid_maintenance_status';END IF;UPDATE asset_maintenance SET status=p_status,completed_at=CASE WHEN p_status='completed' THEN COALESCE(completed_at,now()) ELSE completed_at END,description=CASE WHEN COALESCE(btrim(p_note),'')<>'' THEN concat_ws(E'\n',description,btrim(p_note)) ELSE description END,updated_at=now() WHERE id=p_maintenance_id;UPDATE assets SET status=CASE WHEN p_status='in_progress' THEN 'maintenance' WHEN p_status='completed' AND status='maintenance' THEN 'active' ELSE status END,updated_at=now() WHERE id=v_asset;RETURN true;END$$;GRANT EXECUTE ON FUNCTION update_asset_maintenance_status(uuid,text,text) TO authenticated;
-- Ingestão GPS via backend/Device key
CREATE OR REPLACE FUNCTION ingest_asset_position(p_asset_id uuid,p_device_id uuid,p_key_hash text,p_source_event_id text,p_recorded_at timestamptz,p_latitude double precision,p_longitude double precision,p_speed_kmh numeric DEFAULT NULL,p_heading_degrees numeric DEFAULT NULL,p_accuracy_m numeric DEFAULT NULL,p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(accepted boolean,inside_geofence boolean,transition text,received_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,pg_temp AS $$DECLARE v_org uuid;v_prop uuid;v_neigh uuid;v_linked_device uuid;v_geofence geometry(Polygon,4326);v_enabled boolean;v_previous text;v_last_position timestamptz;v_point geography(Point,4326);v_inside boolean;v_new_state text;v_transition text:='none';v_received timestamptz:=now();v_inserted bigint;v_event_type text;v_severity alert_severity;BEGIN IF p_latitude NOT BETWEEN -90 AND 90 OR p_longitude NOT BETWEEN -180 AND 180 THEN RAISE EXCEPTION 'invalid_coordinates';END IF;IF p_recorded_at IS NULL OR p_recorded_at>now()+interval '10 minutes' THEN RAISE EXCEPTION 'invalid_recorded_at';END IF;IF p_speed_kmh IS NOT NULL AND p_speed_kmh<0 THEN RAISE EXCEPTION 'invalid_speed';END IF;IF p_heading_degrees IS NOT NULL AND(p_heading_degrees<0 OR p_heading_degrees>=360) THEN RAISE EXCEPTION 'invalid_heading';END IF;SELECT a.organization_id,a.property_id,p.neighborhood_id,a.device_id,a.geofence,a.geofence_enabled,a.geofence_state,a.last_position_at INTO v_org,v_prop,v_neigh,v_linked_device,v_geofence,v_enabled,v_previous,v_last_position FROM assets a JOIN properties p ON p.id=a.property_id WHERE a.id=p_asset_id;IF NOT FOUND THEN RAISE EXCEPTION 'asset_not_found';END IF;IF v_linked_device IS NULL OR v_linked_device<>p_device_id THEN RAISE EXCEPTION 'asset_device_mismatch';END IF;IF NOT EXISTS(SELECT 1 FROM device_ingest_keys k WHERE k.device_id=p_device_id AND k.organization_id=v_org AND k.key_hash=p_key_hash AND k.status='active' AND(k.expires_at IS NULL OR k.expires_at>now())) THEN RAISE EXCEPTION 'invalid_device_key';END IF;UPDATE device_ingest_keys SET last_used_at=now() WHERE device_id=p_device_id AND key_hash=p_key_hash AND status='active';v_point:=ST_SetSRID(ST_MakePoint(p_longitude,p_latitude),4326)::geography;IF v_enabled AND v_geofence IS NOT NULL THEN v_inside:=ST_Covers(v_geofence,v_point::geometry);ELSE v_inside:=NULL;END IF;INSERT INTO asset_positions(organization_id,asset_id,device_id,source_event_id,position,recorded_at,received_at,speed_kmh,heading_degrees,accuracy_m,inside_geofence,metadata) VALUES(v_org,p_asset_id,p_device_id,p_source_event_id,v_point,p_recorded_at,v_received,p_speed_kmh,p_heading_degrees,p_accuracy_m,v_inside,COALESCE(p_metadata,'{}'::jsonb)) ON CONFLICT(asset_id,source_event_id) WHERE source_event_id IS NOT NULL DO NOTHING RETURNING id INTO v_inserted;IF v_inserted IS NULL AND p_source_event_id IS NOT NULL THEN RETURN QUERY SELECT false,ap.inside_geofence,'duplicate'::text,ap.received_at FROM asset_positions ap WHERE ap.asset_id=p_asset_id AND ap.source_event_id=p_source_event_id LIMIT 1;RETURN;END IF;IF v_last_position IS NULL OR p_recorded_at>=v_last_position THEN IF v_enabled AND v_geofence IS NOT NULL THEN v_new_state:=CASE WHEN v_inside THEN 'inside' ELSE 'outside' END;ELSE v_new_state:='unknown';END IF;UPDATE assets SET location=v_point,last_position_at=p_recorded_at,geofence_state=v_new_state,updated_at=now() WHERE id=p_asset_id;IF v_enabled AND v_geofence IS NOT NULL THEN IF v_previous='inside' AND v_new_state='outside' THEN v_transition:='exit';v_event_type:='asset_geofence_exit';v_severity:='high';ELSIF v_previous='outside' AND v_new_state='inside' THEN v_transition:='return';v_event_type:='asset_geofence_return';v_severity:='informational';ELSIF v_previous='unknown' AND v_new_state='outside' THEN v_transition:='outside_detected';v_event_type:='asset_geofence_outside_detected';v_severity:='attention';END IF;IF v_event_type IS NOT NULL THEN INSERT INTO security_events(organization_id,neighborhood_id,property_id,device_id,asset_id,event_type,severity,human_validation_status,occurred_at,metadata) VALUES(v_org,v_neigh,v_prop,p_device_id,p_asset_id,v_event_type,v_severity,'not_required',p_recorded_at,jsonb_build_object('source','asset_geofence_rule','latitude',p_latitude,'longitude',p_longitude,'speedKmh',p_speed_kmh,'accuracyM',p_accuracy_m,'geofenceState',v_new_state));END IF;END IF;ELSE v_transition:='historical';END IF;RETURN QUERY SELECT true,v_inside,v_transition,v_received;END$$;REVOKE ALL ON FUNCTION ingest_asset_position(uuid,uuid,text,text,timestamptz,double precision,double precision,numeric,numeric,numeric,jsonb) FROM PUBLIC,authenticated,anonymous;
CREATE OR REPLACE FUNCTION get_asset_security_feed() RETURNS TABLE(id uuid,property_id uuid,property_name text,name text,asset_type text,status text,manufacturer text,model text,serial_number text,manufacture_year smallint,external_identifier text,device_id uuid,device_name text,geofence_enabled boolean,geofence_state text,latitude double precision,longitude double precision,last_position_at timestamptz,maintenance_open bigint,documents_expiring bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public,auth AS $$SELECT a.id,a.property_id,p.name,a.name,a.asset_type,a.status,a.manufacturer,a.model,a.serial_number,a.manufacture_year,a.external_identifier,a.device_id,d.name,a.geofence_enabled,a.geofence_state,CASE WHEN a.location IS NULL THEN NULL ELSE ST_Y(a.location::geometry) END,CASE WHEN a.location IS NULL THEN NULL ELSE ST_X(a.location::geometry) END,a.last_position_at,(SELECT count(*) FROM asset_maintenance m WHERE m.asset_id=a.id AND m.status IN('planned','in_progress')),(SELECT count(*) FROM asset_documents doc WHERE doc.asset_id=a.id AND doc.status='active' AND doc.expires_at IS NOT NULL AND doc.expires_at<=current_date+30) FROM assets a JOIN properties p ON p.id=a.property_id LEFT JOIN devices d ON d.id=a.device_id WHERE app_has_scope_access(a.organization_id,p.neighborhood_id,a.property_id) ORDER BY a.name$$;GRANT EXECUTE ON FUNCTION get_asset_security_feed() TO authenticated;
CREATE OR REPLACE FUNCTION get_asset_position_history(p_asset_id uuid,p_limit integer DEFAULT 200) RETURNS TABLE(id bigint,recorded_at timestamptz,received_at timestamptz,latitude double precision,longitude double precision,speed_kmh numeric,heading_degrees numeric,accuracy_m numeric,inside_geofence boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public,auth AS $$SELECT ap.id,ap.recorded_at,ap.received_at,ST_Y(ap.position::geometry),ST_X(ap.position::geometry),ap.speed_kmh,ap.heading_degrees,ap.accuracy_m,ap.inside_geofence FROM asset_positions ap JOIN assets a ON a.id=ap.asset_id JOIN properties p ON p.id=a.property_id WHERE ap.asset_id=p_asset_id AND app_has_scope_access(a.organization_id,p.neighborhood_id,a.property_id) ORDER BY ap.recorded_at DESC LIMIT LEAST(GREATEST(COALESCE(p_limit,200),1),1000)$$;GRANT EXECUTE ON FUNCTION get_asset_position_history(uuid,integer) TO authenticated;
CREATE OR REPLACE FUNCTION get_asset_documents(p_asset_id uuid) RETURNS TABLE(id uuid,document_type text,title text,document_reference text,issued_at date,expires_at date,status text,storage_status text,created_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public,auth AS $$SELECT doc.id,doc.document_type,doc.title,doc.document_reference,doc.issued_at,doc.expires_at,doc.status,doc.storage_status,doc.created_at FROM asset_documents doc JOIN assets a ON a.id=doc.asset_id JOIN properties p ON p.id=a.property_id WHERE doc.asset_id=p_asset_id AND app_has_scope_access(a.organization_id,p.neighborhood_id,a.property_id) ORDER BY doc.expires_at NULLS LAST,doc.created_at DESC$$;GRANT EXECUTE ON FUNCTION get_asset_documents(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION get_asset_maintenance(p_asset_id uuid) RETURNS TABLE(id uuid,maintenance_type text,description text,scheduled_at timestamptz,completed_at timestamptz,status text,meter_hours numeric,created_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public,auth AS $$SELECT m.id,m.maintenance_type,m.description,m.scheduled_at,m.completed_at,m.status,m.meter_hours,m.created_at FROM asset_maintenance m JOIN assets a ON a.id=m.asset_id JOIN properties p ON p.id=a.property_id WHERE m.asset_id=p_asset_id AND app_has_scope_access(a.organization_id,p.neighborhood_id,a.property_id) ORDER BY COALESCE(m.scheduled_at,m.created_at) DESC$$;GRANT EXECUTE ON FUNCTION get_asset_maintenance(uuid) TO authenticated;
